require 'inc/connect.php';require 'inc/auth.php';require 'inc/password_security.php';$error='';$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$q=$db->prepare('SELECT pwd FROM tbl_users WHERE u_id=?');$q->execute([$_SESSION['u_id']]);$hash=$q->fetchColumn();if(!verifyUserPassword($current,$hash))$error='Current password is incorrect.';elseif(strlen($new)<12||!preg_match('/[A-Za-z]/',$new)||!preg_match('/[0-9]/',$new))$error='Use at least 12 characters with letters and numbers.';elseif($new!==$confirm)$error='The new passwords do not match.';else{$db->prepare('UPDATE tbl_users SET pwd=? WHERE u_id=?')->execute([hashUserPassword($new),$_SESSION['u_id']]);$q=$db->prepare('SELECT id FROM tbl_password_updates WHERE user_id=? LIMIT 1');$q->execute([$_SESSION['u_id']]);$historyId=$q->fetchColumn();if($historyId)$db->prepare('UPDATE tbl_password_updates SET password_updated=1,updated_at=NOW() WHERE id=?')->execute([$historyId]);else $db->prepare('INSERT INTO tbl_password_updates(user_id,password_updated) VALUES(?,1)')->execute([$_SESSION['u_id']]);$_SESSION['password_change_required']=false;$ok='Password updated.';audit_log($db,$_SESSION['u_id'],'CHANGE_PASSWORD','tbl_users',$_SESSION['u_id']);}}
